import './style.css';

if (window.navigator.userAgent.match(/CrOS/)) {
  const getTranslation = (key) => chrome.i18n.getMessage(key);
  chrome.storage.local.get(
    [
      'ohInstructionAccepted',
      'ohGoogleCounter',
      'ohShowInstallationInstructionsLater',
    ],
    (result) => {
      if (result.ohInstructionAccepted) {
        return;
      }

      const ohGoogleCounter = (result.ohGoogleCounter || 0) + 1;

      chrome.storage.local.set({ ohGoogleCounter });

      if (ohGoogleCounter < 10 && result.ohShowInstallationInstructionsLater) {
        return;
      }

      const installPrompt = document.createElement('div');

      const closeButtonMarkup = `<button class="close" aria-label="${getTranslation(
        'chromeos_settings_prompt_close_prompt'
      )}"><span aria-hidden="true">×</span></button>`;

      const installPromptCollapsedLayout = `
        <div class="prompt-text">${getTranslation(
          'chromeos_settings_prompt_title_collapsed'
        )}</div>
        <div class="buttons-group">
          <button class="accept" role="button">${getTranslation(
            'chromeos_settings_prompt_show_tutorial'
          )}</button>
          <button class="cancel" role="button">${getTranslation(
            'chromeos_settings_prompt_close_prompt'
          )}</button>
        </div>
        ${closeButtonMarkup}
      `;

      const installPromptExpandedLayout = `
            <div class="tutorial-header">
              ${closeButtonMarkup}
            </div>
            <div class="tutorial-container">
              <h2 class="instructions-header">${getTranslation(
                'chromeos_settings_prompt_title_expanded'
              )}</h2>
              <div class="instructions-layout">
                <div class="change-instructions"><img src="https://oceanhero.today/change-search.gif" alt="${getTranslation(
                  'cromeos_settings_img_alt'
                )}"></div>
                <div class="step-by-step">
                 <div class="steps">
                    <h3 class="instructions-header">
                        ${getTranslation(
                          'chromeos_settings_prompt_title_expanded_sub'
                        )} 
                    </h3> 
                    <ol class="instructions-order">
                      <li>
                        <span class="counter">1.</span> <span class="instruction">${getTranslation(
                          'chromeos_settings_prompt_instruction_step_1'
                        )}</span>
                      </li>
                      <li>
                        <span class="counter">2.</span> <span class="instruction">${getTranslation(
                          'chromeos_settings_prompt_instruction_step_2'
                        )}</span>
                      </li>
                      <li>
                        <span class="counter">3.</span> <span class="instruction">${getTranslation(
                          'chromeos_settings_prompt_instruction_step_3'
                        )}</span>
                      </li>
                      <li>
                        <span class="counter">4.</span> <span class="instruction">${getTranslation(
                          'chromeos_settings_prompt_instruction_step_4'
                        )}</span>
                      </li>
                    </ol>
                </div>
                <div class="buttons-group">
                  <button class="accept" role="button">${getTranslation(
                    'chromeos_settings_prompt_success'
                  )}</button>
                  <a class="form-link" target="_blank" href="https://docs.google.com/forms/d/e/1FAIpQLSdfDOFcMYIn8mS4HWM5hrqAxmUpRlWSx8xGHDZg75HkE5RFhw/viewform">${getTranslation(
                    'chromeos_settings_prompt_help'
                  )}</a>
                </div>
                </div>
              </div>
            </div>
        `;

      // eslint-disable-next-line prefer-const
      let cleanupEventListeners;

      const discardPrompt = () => {
        // Treat the second discarding as if user has seen the instruction already;
        chrome.storage.local.set(
          ohGoogleCounter >= 10
            ? { ohInstructionAccepted: true }
            : { ohShowInstallationInstructionsLater: true }
        );
        cleanupEventListeners();
        document.body.classList.remove('oh-prompt');
        document.body.classList.remove('with-tutorial');
        installPrompt.parentNode.removeChild(installPrompt);
      };

      const confirmPrompt = () => {
        chrome.storage.local.set({ ohInstructionAccepted: true });
        cleanupEventListeners();
        document.body.classList.remove('oh-prompt');
        document.body.classList.remove('with-tutorial');
        installPrompt.parentNode.removeChild(installPrompt);
      };

      const showTutorial = () => {
        cleanupEventListeners();
        installPrompt.classList.add('with-tutorial');
        document.body.classList.add('with-tutorial');
        installPrompt.innerHTML = installPromptExpandedLayout;
        document
          .querySelector('#change-engine-prompt .accept')
          .addEventListener('click', confirmPrompt);
        document
          .querySelector('#change-engine-prompt .close')
          .addEventListener('click', discardPrompt);
      };

      cleanupEventListeners = () => {
        if (document.querySelector('#change-engine-prompt .cancel')) {
          document
            .querySelector('#change-engine-prompt .cancel')
            .removeEventListener('click', discardPrompt);
        }

        if (document.querySelector('#change-engine-prompt .close')) {
          document
            .querySelector('#change-engine-prompt .close')
            .removeEventListener('click', discardPrompt);
        }

        if (document.querySelector('#change-engine-prompt .accept')) {
          document
            .querySelector('#change-engine-prompt .accept')
            .removeEventListener('click', showTutorial);
        }

        if (document.querySelector('#change-engine-prompt .accept')) {
          document
            .querySelector('#change-engine-prompt .accept')
            .removeEventListener('click', confirmPrompt);
        }
      };

      const renderPrompt = () => {
        installPrompt.setAttribute('id', 'change-engine-prompt');
        installPrompt.innerHTML = installPromptCollapsedLayout;
        document.body.classList.add('oh-prompt');
        document.body.prepend(installPrompt);
        document
          .querySelector('#change-engine-prompt .cancel')
          .addEventListener('click', discardPrompt);
        document
          .querySelector('#change-engine-prompt .close')
          .addEventListener('click', discardPrompt);
        document
          .querySelector('#change-engine-prompt .accept')
          .addEventListener('click', showTutorial);
      };

      renderPrompt();
    }
  );
}
